@import url('https://fonts.googleapis.com/css2?family=Literata:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600;700&display=swap');

/* E-Ink — pure grayscale paper, high contrast, serif body, matte, zero gloss */
.theme-e-ink {
  --bg: oklch(0.94 0.002 90);
  --surface: oklch(0.975 0.002 90);
  --surface-2: oklch(0.89 0.002 90);
  --fg: oklch(0.16 0 0);
  --fg-muted: oklch(0.46 0 0);
  --accent: oklch(0.16 0 0);
  --accent-fg: oklch(0.975 0.002 90);
  --accent-2: oklch(0.55 0.19 30); /* the single functional accent */
  --line: oklch(0.62 0 0);
  --success: oklch(0.35 0 0);
  --warning: oklch(0.5 0 0);
  --danger: oklch(0.55 0.19 30);

  --radius: 0.125rem;
  --radius-sm: 0.0625rem;
  --radius-lg: 0.25rem;
  --radius-pill: 0.25rem;

  --shadow-1: none;
  --shadow-2: none;
  --shadow-3: none;
  --glow: 0 0 0 2px var(--fg);

  --border-width: 1px;
  --blur-amount: 0px;

  --font-display: "Literata", Georgia, serif;
  --font-body: "Literata", Georgia, serif;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;

  --tracking-display: -0.01em;
  --label-transform: uppercase;
  --label-tracking: 0.16em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-e-ink h1,
.theme-e-ink h2,
.theme-e-ink h3 {
  font-family: var(--font-display);
  font-weight: 600;
  letter-spacing: var(--tracking-display);
}

.theme-e-ink p {
  line-height: 1.75;
}

/* signature */
.theme-e-ink *, .theme-e-ink *::before, .theme-e-ink *::after { transition: none !important; animation: none !important; }
.theme-e-ink img { filter: grayscale(1); }
.theme-e-ink h1 { font-weight: 700; }

/* depth */
.theme-e-ink thead th { font-family: var(--font-mono); text-transform: uppercase; letter-spacing: 0.12em; font-size: 0.7em; font-weight: 500; border-bottom: 2px solid var(--fg); text-align: left; }
.theme-e-ink td { border-bottom: 1px dotted var(--line); }
/* physical: row hover = a dither pass, like a partial screen refresh */
.theme-e-ink tbody tr:hover { background: repeating-linear-gradient(45deg, oklch(0.16 0 0 / 8%) 0 1px, transparent 1px 3px); }
.theme-e-ink input, .theme-e-ink select, .theme-e-ink textarea { border: 1px solid var(--fg); border-radius: var(--radius-sm); background: var(--surface); }
.theme-e-ink input:focus, .theme-e-ink select:focus, .theme-e-ink textarea:focus { outline: 2px solid var(--fg); outline-offset: 1px; box-shadow: none; }
.theme-e-ink a { color: var(--fg); text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 3px; }
.theme-e-ink a:hover { background: var(--fg); color: var(--bg); text-decoration: none; }
.theme-e-ink button:active { background: var(--fg); color: var(--bg); }
.theme-e-ink kbd { font-family: var(--font-mono); font-size: 0.85em; padding: 0.1em 0.4em; border: 1px solid var(--fg); border-radius: var(--radius-sm); background: var(--surface); }
.theme-e-ink ::selection { background: var(--fg); color: var(--bg); }
.theme-e-ink ::-webkit-scrollbar { width: 8px; height: 8px; }
.theme-e-ink ::-webkit-scrollbar-track { background: var(--surface-2); }
.theme-e-ink ::-webkit-scrollbar-thumb { background: var(--fg); border-radius: 0; }
.theme-e-ink .label-caps { font-family: var(--font-mono); font-weight: 500; }
.theme-e-ink .themed-border { border: 1px solid var(--fg); }

/* alt mode: night reader — warm-free dark slate, ink flips to bone white */
.theme-e-ink.alt-mode {
  --bg: oklch(0.145 0.002 90.0);
  --surface: oklch(0.185 0.002 90.0);
  --surface-2: oklch(0.225 0.002 90.0);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.70 0.01 90);
  --line: oklch(1 0 0 / 14%);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --accent: oklch(0.97 0.005 90);
  --accent-fg: oklch(0.145 0.002 90);
  --accent-2: oklch(0.68 0.17 30);
  --danger: oklch(0.68 0.17 30);
  --success: oklch(0.8 0 0);
  --warning: oklch(0.66 0 0);
  --line: oklch(0.97 0.005 90 / 35%);
  --shadow-1: none;
  --shadow-2: none;
  --shadow-3: none;
  --glow: 0 0 0 2px var(--fg);
}
.theme-e-ink.alt-mode tbody tr:hover { background: repeating-linear-gradient(45deg, oklch(0.97 0.005 90 / 10%) 0 1px, transparent 1px 3px); }
.theme-e-ink.alt-mode input, .theme-e-ink.alt-mode select, .theme-e-ink.alt-mode textarea, .theme-e-ink.alt-mode kbd, .theme-e-ink.alt-mode thead th, .theme-e-ink.alt-mode .themed-border { border-color: var(--fg); }
.theme-e-ink.alt-mode img { filter: grayscale(1) brightness(0.85); }
.theme-e-ink.alt-mode ::-webkit-scrollbar-thumb { background: var(--fg); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"], [class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
